sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Store the reservation status as a string for clean comparison
    var reservationStatus = current.reservation_status.toString();

    // Set up a GlideRecord to find and update the related Workspace Options record
    var workspaceGR = new GlideRecord('x_1903615_worksp_0_workspace_options');

    // Use the workspace reference field on Reservation Tracker to find the related record
    if (!workspaceGR.get(current.workspace)) {
        gs.warn('Sync Workspace Status BR: No related Workspace Options record found for reservation ' + current.number);
        return;
    }

    // If checking in or checked in, workspace becomes unavailable
    if (reservationStatus == 'pending_check_in' || reservationStatus == 'checked_in') {
        workspaceGR.setValue('status', 'unavailable');
    }
    // If checked out, no-show, or cancelled, workspace becomes available again
    else if (reservationStatus == 'checked_out' || reservationStatus == 'no_show' || reservationStatus == 'cancelled') {
        workspaceGR.setValue('status', 'available');
    }

    // Save the change to the other table's record — required in after business rules
    workspaceGR.update();

})(current, previous);
